import { copyFileSync, cpSync, mkdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

// Explicit source allowlist: never copy local invites, credentials, user data or media.
const target = resolve('.vercel/linux-validation');
// This directory is exclusively generated by this script, never a source checkout.
rmSync(target, { recursive: true, force: true });
mkdirSync(target, { recursive: true });
for (const name of ['backend', 'config', 'web', 'public', 'vendor/workspace_shared', 'vendor/anatomy/kit', 'native', 'experiments']) {
  cpSync(name, `${target}/${name}`, { recursive: true, filter: path => !path.includes('__pycache__') });
}
copyFileSync('vendor/anatomy/LICENSE', `${target}/vendor/anatomy/LICENSE`);
for (const name of ['package.json', 'package-lock.json', 'pyproject.toml', 'uv.lock', 'requirements.txt', 'vercel.json', 'main.py', 'index.html', 'tsconfig.json', 'vite.config.ts', 'eslint.config.js', '.vercelignore']) {
  copyFileSync(name, `${target}/${name}`);
}
mkdirSync(`${target}/scripts`, { recursive: true });
for (const name of ['vercel-build.mjs', 'pwa-build.mjs', 'service-worker.js', 'check-deployment-sources.mjs']) copyFileSync(`scripts/${name}`, `${target}/scripts/${name}`);
mkdirSync(`${target}/.vercel`, { recursive: true });
copyFileSync('.vercel/project.json', `${target}/.vercel/project.json`);
// An empty file prevents the CLI from trying to pull real project credentials.
writeFileSync(`${target}/.vercel/.env.preview.local`, '');
const config = JSON.parse(readFileSync(`${target}/vercel.json`, 'utf8'));
if (config.framework !== 'fastapi') throw new Error('Expected the FastAPI deployment framework');
console.log(`Prepared sanitized source at ${target}`);
